import {collectCopy,encryptCopy,decryptCopy,validateCopy} from './backup.js';
import {csv} from './report-model.js';
export function createControl({db,root,state,guard,ready,render,notice,esc,date}){
 let generation=0,audit=[],members=[],loaded=false,busy=false,error='',filter='',page=0;
 const allowed=()=>state().me?.role==='admin'&&ready();
 async function authorize(){if(!allowed())throw Error('Acceso exclusivo del administrador.');await guard();const r=await db.rpc('charito_security_status');if(r.error||!r.data?.can_manage_users||!r.data?.session_valid||!r.data?.ready)throw Error('Verifica tu acceso de administrador.');}
 const actions={INSERT:'Creación',UPDATE:'Modificación',DELETE:'Eliminación',logout:'Cierre de sesión'};
 function auditView(){const list=audit.filter(r=>!filter||r.entity===filter),slice=list.slice(page*25,(page+1)*25);return `<div class="card full" data-control-audit><div class="control-heading"><h2>Actividad reciente</h2><button type="button" class="secondary" data-control-refresh ${busy?'disabled':''}>Actualizar</button></div>${error?`<div class="warn" role="alert">${esc(error)}</div>`:''}<div class="control-toolbar"><label>Registro<select data-control-filter><option value="">Todos</option>${[...new Set(audit.map(r=>r.entity))].map(e=>`<option ${filter===e?'selected':''}>${esc(e)}</option>`).join('')}</select></label><span class="small muted">Últimos ${audit.length} eventos</span><button type="button" class="secondary" data-audit-export ${!audit.length?'disabled':''}>Descargar CSV</button></div>${busy&&!loaded?'<p role="status">Cargando…</p>':`<div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Registro</th><th>Acción</th></tr></thead><tbody>${slice.map(r=>`<tr><td data-label="Fecha">${date(r.created_at)}</td><td data-label="Usuario">${esc(members.find(m=>m.user_id===r.actor_id)?.display_name||r.actor_id?.slice(0,8)||'Sistema')}</td><td data-label="Registro">${esc(r.entity.replace('charito_',''))}<small class="control-id">${esc(r.entity_id||'')}</small></td><td data-label="Acción">${esc(actions[r.action]||r.action)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Sin eventos</td></tr>'}</tbody></table></div>`}<div class="control-pager"><button type="button" class="secondary" data-control-page="${page-1}" ${page===0?'disabled':''}>Anterior</button><span>${page+1} / ${Math.max(1,Math.ceil(list.length/25))}</span><button type="button" class="secondary" data-control-page="${page+1}" ${(page+1)*25>=list.length?'disabled':''}>Siguiente</button></div></div>`;}
 function view(){if(!allowed())return '';return `<div class="grid control-panel"><div class="card"><h2>Copia cifrada de datos</h2><p class="small muted">Datos del negocio; sin fotos ni accesos.</p><form data-form="control_backup"><label>Clave de la copia<input name="backup_password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><label>Repetir clave<input name="backup_repeat" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><button>Crear y descargar copia</button><span data-copy-progress class="small" role="status"></span></form></div><div class="card"><h2>Verificar una copia</h2><form data-form="control_verify"><label>Archivo<input name="backup_file" type="file" accept=".charito,application/json" required></label><label>Clave de la copia<input name="backup_password" type="password" autocomplete="off" required></label><button class="secondary">Verificar archivo</button><output data-copy-result role="status"></output></form></div>${auditView()}</div>`;}
 function paintAudit(){const el=root?.querySelector('[data-control-audit]');if(el&&state().view==='control'&&allowed())el.outerHTML=auditView();}
 async function enter(view,force=false){if(view!=='control'||!allowed()||busy||loaded&&!force)return;const run=generation,owner=state().user?.id;busy=true;error='';try{await authorize();const [r,m]=await Promise.all([db.from('charito_security_audit').select('id,actor_id,entity,entity_id,action,created_at').order('id',{ascending:false}).limit(200),db.from('charito_members').select('user_id,display_name').order('user_id').limit(1000)]);if(r.error||m.error)throw Error((r.error||m.error).message);if(run!==generation||owner!==state().user?.id||!allowed())return;audit=r.data||[];members=m.data||[];loaded=true;page=0;}catch(e){if(run===generation)error='No se pudo consultar la actividad. '+e.message;}finally{if(run===generation){busy=false;paintAudit();}}}
 function download(text,name,type){if(window.AndroidHost?.saveDocument){const error=window.AndroidHost.saveDocument(text,name,type.split(';')[0]);if(typeof error==='string'&&error)throw Error(error);return;}if(window.AndroidHost?.saveJson&&type==='application/json'){if(text.length>20000000)throw Error('Actualiza la APK para guardar esta copia.');window.AndroidHost.saveJson(text);return;}const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function submit(action,f){if(!action?.startsWith('control_'))return false;const run=generation,owner=state().user?.id,active=()=>run===generation&&state().user?.id===owner&&allowed();try{await authorize();if(!active())throw Error('La sesión cambió.');if(action==='control_backup'){
   const password=f.elements.backup_password.value;if(password!==f.elements.backup_repeat.value)throw Error('Las claves no coinciden.');
   if(!window.confirm('Guardarás datos de clientes y caja. Conserva el archivo y su clave por separado. Haz la copia sin operaciones en curso. ¿Continuar?'))return true;
   const copy=await collectCopy(db,guard,active,(n,t)=>{const el=f.querySelector('[data-copy-progress]');if(el)el.textContent=`${n} / ${t}`;});const encrypted=await encryptCopy(copy,password);validateCopy(await decryptCopy(encrypted,password));await authorize();if(!active())return true;download(encrypted,`Charito-${new Date().toISOString().slice(0,10)}.charito`,'application/json');f.reset();notice('Copia cifrada creada y verificada.');
  }else if(action==='control_verify'){const file=f.elements.backup_file.files[0];if(!file||file.size>96*1024*1024)throw Error('Selecciona una copia de hasta 96 MB.');const copy=await decryptCopy(await file.text(),f.elements.backup_password.value);await authorize();if(!active())return true;const summary=validateCopy(copy);f.elements.backup_password.value='';const output=f.querySelector('[data-copy-result]');if(output)output.textContent=`Copia válida · ${summary.tables} tablas · ${summary.rows} registros · ${date(summary.finished)}. La base de datos no se ha modificado.`;}
  return true;
 }finally{if(f.elements.backup_password)f.elements.backup_password.value='';if(f.elements.backup_repeat)f.elements.backup_repeat.value='';}}
 async function click(b){if(b.hasAttribute('data-control-refresh')){await enter('control',true);return true;}if(b.hasAttribute('data-control-page')){page=Math.max(0,Number(b.dataset.controlPage));paintAudit();return true;}if(b.hasAttribute('data-audit-export')){const run=generation,owner=state().user?.id;await authorize();if(run!==generation||state().user?.id!==owner||!allowed())return true;download(csv([['Fecha','Actor','Registro','ID','Acción'],...audit.filter(r=>!filter||r.entity===filter).map(r=>[r.created_at,r.actor_id,r.entity,r.entity_id,r.action])]),'charito-actividad.csv','text/csv;charset=utf-8');return true;}return false;}
 function input(e){if(e.target.hasAttribute('data-control-filter')){filter=e.target.value;page=0;paintAudit();}}
 function clear(){generation++;audit=[];members=[];loaded=false;busy=false;error='';filter='';page=0;}
 return {view,enter,submit,click,input,clear};
}
